import { promises as fs } from "node:fs";
import path from "node:path";
import { list, put, get } from "@vercel/blob";
import { GuideSchema, type Guide } from "./schema";
import { CURATED } from "../../data/guides";

/**
 * Two sources of guides:
 *  - curated: checked into the repo (data/guides/*.json), generated by the same agent and then reviewed
 *  - generated: created live by users; stored in Vercel Blob in production, or .data/ locally
 */

const useBlob = !!process.env.BLOB_READ_WRITE_TOKEN;
// On Vercel the deployment filesystem is read-only, so without Blob we can only use /tmp
// (per instance, not durable). Connect a Blob store for shareable live-generated guides.
const LOCAL_DIR = process.env.VERCEL ? "/tmp/generated" : path.join(process.cwd(), ".data", "generated");

export function curatedGuides(): Guide[] {
  return CURATED;
}

export async function saveGenerated(guide: Guide): Promise<void> {
  const json = JSON.stringify(guide, null, 2);
  if (useBlob) {
    await put(`guides/${guide.slug}.json`, json, {
      access: "private",
      contentType: "application/json",
      addRandomSuffix: false,
      allowOverwrite: true,
    });
    return;
  }
  await fs.mkdir(LOCAL_DIR, { recursive: true });
  await fs.writeFile(path.join(LOCAL_DIR, `${guide.slug}.json`), json);
}

async function readGenerated(slug: string): Promise<Guide | null> {
  try {
    if (useBlob) {
      const r = await get(`guides/${slug}.json`, { access: "private", useCache: false });
      if (!r || r.statusCode !== 200) return null;
      return GuideSchema.parse(await new Response(r.stream).json());
    }
    const raw = await fs.readFile(path.join(LOCAL_DIR, `${slug}.json`), "utf8");
    return GuideSchema.parse(JSON.parse(raw));
  } catch {
    return null;
  }
}

export async function getGuide(slug: string): Promise<{ guide: Guide; source: "curated" | "generated" } | null> {
  const curated = CURATED.find((g) => g.slug === slug);
  if (curated) return { guide: curated, source: "curated" };
  const gen = await readGenerated(slug);
  return gen ? { guide: gen, source: "generated" } : null;
}

export type GuideSummary = Pick<Guide, "slug" | "appName" | "category" | "summary"> & {
  difficulty: Guide["verdict"]["difficulty"];
  approvalWait: string;
  setupTime: string;
  source: "curated" | "generated";
  generatedAt: string;
  logo?: string;
  managed?: boolean | null;
};

const toSummary = (g: Guide, source: "curated" | "generated"): GuideSummary => ({
  slug: g.slug,
  appName: g.appName,
  category: g.category,
  summary: g.summary,
  difficulty: g.verdict.difficulty,
  approvalWait: g.verdict.approvalWait,
  setupTime: g.verdict.setupTime,
  source,
  generatedAt: g.meta.generatedAt,
  logo: g.composio?.logo,
  managed: g.composio ? g.composio.managedOAuth : null,
});

export async function listGuides(): Promise<GuideSummary[]> {
  const out = CURATED.map((g) => toSummary(g, "curated"));
  const seen = new Set(out.map((g) => g.slug));
  try {
    const slugs: string[] = [];
    if (useBlob) {
      const { blobs } = await list({ prefix: "guides/", limit: 200 });
      blobs.forEach((b) => slugs.push(b.pathname.replace(/^guides\//, "").replace(/\.json$/, "")));
    } else {
      const files = await fs.readdir(LOCAL_DIR).catch(() => [] as string[]);
      files.filter((f) => f.endsWith(".json")).forEach((f) => slugs.push(f.replace(/\.json$/, "")));
    }
    const fresh = slugs.filter((s) => !seen.has(s));
    const guides = await Promise.all(fresh.map(readGenerated));
    guides.forEach((g) => g && out.push(toSummary(g, "generated")));
  } catch {
    /* listing generated guides is best-effort */
  }
  return out;
}
